solution:
fn last_element(v: &Vec[Int]) -> &Int {
  return &v[v.len() - 1];
}

fn main() -> Int {
  let data = Vec[Int]();
  data.push(5);
  data.push(10);
  data.push(15);
  let last = last_element(&data);
  return *last;
}
